#!/usr/bin/env bun

import { pathToFileURL } from 'node:url';
import { getDefaultWorkDir, getGlobalConfigDir, loadEnvFiles } from './core/config.js';
import type { StatusCallbacks } from './core/types.js';
import { validateWorkflowName } from './core/utils.js';
import { loadWorkflow } from './core/workflow-loader.js';
import { initDefaultConfig } from './setup.js';

// ─── CLI Options ────────────────────────────────────────────────────────────

export interface CliOptions {
  command: 'run' | 'init' | 'help' | 'version';
  workflowName?: string;
  taskPrompt?: string;
  cwd: string;
  workDir?: string;
  maxConcurrent: number;
  verbose: boolean;
  apiKeys: Record<string, string>;
  warnings: string[];
}

// ─── Argument Parsing ───────────────────────────────────────────────────────

const VERSION = '0.1.0';

const USAGE = `Usage: engin <command> [options]

Commands:
  run    <workflow-name> <task-prompt> [options]   Run a workflow
  init                                              Create config directory structure

Options:
  --cwd <path>            Working directory (default: process.cwd())
  --work-dir <path>       Workflow working directory (run only)
  --max-concurrent <n>    Max concurrent tasks (default: 3, run only)
  --verbose               Enable verbose logging
  --api-key <provider=key>  API key (repeatable)
  --help, -h              Show this help message
  --version, -v           Show version`;

export function parseArgs(argv: string[]): CliOptions {
  // 1. Check for --help / -h anywhere (before positional parsing)
  if (argv.includes('--help') || argv.includes('-h')) {
    return {
      command: 'help' as const,
      cwd: process.cwd(),
      maxConcurrent: 3,
      verbose: false,
      apiKeys: {},
      warnings: [],
    };
  }

  // 2. Check for --version / -v anywhere (before positional parsing)
  if (argv.includes('--version') || argv.includes('-v')) {
    return {
      command: 'version' as const,
      cwd: process.cwd(),
      maxConcurrent: 3,
      verbose: false,
      apiKeys: {},
      warnings: [],
    };
  }

  // 3. Separate positionals from flags
  const positionals: string[] = [];
  const flags: string[] = [];
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '--cwd') {
      const val = argv[++i];
      if (val === undefined || val.startsWith('--')) {
        throw new Error(`Missing value for ${arg}\n${USAGE}`);
      }
      flags.push(arg, val);
    } else if (arg === '--work-dir') {
      const val = argv[++i];
      if (val === undefined || val.startsWith('--')) {
        throw new Error(`Missing value for ${arg}\n${USAGE}`);
      }
      flags.push(arg, val);
    } else if (arg === '--max-concurrent') {
      const val = argv[++i];
      if (val === undefined || val.startsWith('--')) {
        throw new Error(`Missing value for ${arg}\n${USAGE}`);
      }
      flags.push(arg, val);
    } else if (arg === '--verbose') {
      flags.push(arg);
    } else if (arg === '--api-key') {
      const val = argv[++i];
      if (val === undefined || val.startsWith('--')) {
        throw new Error(`Missing value for ${arg}\n${USAGE}`);
      }
      flags.push(arg, val);
    } else if (arg.startsWith('--')) {
      throw new Error(`Unknown flag: "${arg}"\n${USAGE}`);
    } else {
      positionals.push(arg);
    }
    i++;
  }

  if (positionals.length === 0) {
    throw new Error(`Missing command\n${USAGE}`);
  }

  const command = positionals[0];

  // 4. Parse common flags
  let cwd = process.cwd();
  let verbose = false;
  const apiKeys: Record<string, string> = {};
  const warnings: string[] = [];
  let apiKeyWarningIssued = false;
  let workDir: string | undefined;
  let maxConcurrent = 3;

  for (let j = 0; j < flags.length; j++) {
    const flag = flags[j];
    if (flag === '--cwd') {
      cwd = flags[++j];
    } else if (flag === '--work-dir') {
      workDir = flags[++j];
    } else if (flag === '--max-concurrent') {
      const raw = flags[++j];
      const parsed = Number(raw);
      if (!Number.isFinite(parsed) || parsed < 1 || !Number.isInteger(parsed)) {
        throw new Error(`--max-concurrent must be a positive integer, got "${raw}"\n${USAGE}`);
      }
      maxConcurrent = parsed;
    } else if (flag === '--verbose') {
      verbose = true;
    } else if (flag === '--api-key') {
      const pair = flags[++j];
      const eqIdx = pair.indexOf('=');
      if (eqIdx < 0) {
        throw new Error(`Invalid --api-key format: expected provider=key, got "${pair}"\n${USAGE}`);
      }
      const provider = pair.slice(0, eqIdx);
      const key = pair.slice(eqIdx + 1);
      apiKeys[provider] = key;
      if (!apiKeyWarningIssued) {
        warnings.push(
          'API keys passed via --api-key are visible in process listings. Consider using environment variables instead.',
        );
        apiKeyWarningIssued = true;
      }
    }
  }

  if (command === 'init') {
    if (positionals.length > 1) {
      throw new Error(`Unexpected argument: "${positionals[1]}"\n${USAGE}`);
    }
    return { command: 'init', cwd, verbose, maxConcurrent, apiKeys, warnings };
  }

  // Any non-init positional is treated as "run" with the first positional as the workflow name.
  const workflowName = command; // first positional is workflow name when implicit run
  const taskPrompt = positionals[1];

  if (!taskPrompt) {
    throw new Error(`Missing required <task-prompt> for run command\n${USAGE}`);
  }

  if (positionals.length > 2) {
    throw new Error(`Unexpected argument: "${positionals[2]}"\n${USAGE}`);
  }

  return {
    command: 'run',
    workflowName,
    taskPrompt,
    cwd,
    workDir,
    maxConcurrent,
    verbose,
    apiKeys,
    warnings,
  };
}

// ─── Time Formatting ────────────────────────────────────────────────────────

export function formatTime(): string {
  const now = new Date();
  const h = String(now.getHours()).padStart(2, '0');
  const m = String(now.getMinutes()).padStart(2, '0');
  const s = String(now.getSeconds()).padStart(2, '0');
  return `[${h}:${m}:${s}]`;
}

// ─── Status Callbacks ───────────────────────────────────────────────────────

export function createStatusCallbacks(verbose: boolean): StatusCallbacks {
  const callbacks: StatusCallbacks = {
    onWorkflowStart: (info) => {
      console.log(`${formatTime()} 🚀 Workflow started: "${info.taskPrompt}" (resumed: ${info.resumed})`);
    },
    onWorkflowComplete: (info) => {
      console.log(
        `${formatTime()} 🎉 Workflow complete in ${info.totalDurationMs / 1000}s (${info.agentCount} agents)`,
      );
    },
    onWorkflowFailed: (info) => {
      console.log(`${formatTime()} 💥 Workflow failed at phase ${info.phase}: ${info.error.message}`);
    },
    onPhaseStart: (info) => {
      console.log(`${formatTime()} 📦 Phase started: ${info.phase} (round ${info.round})`);
    },
    onPhaseComplete: (info) => {
      console.log(`${formatTime()} ✅ Phase completed: ${info.phase} (${info.durationMs / 1000}s)`);
    },
    onAgentSpawn: (info) => {
      console.log(`${formatTime()} ⏳ Agent spawned: ${info.agentId} (profile: ${info.profile})`);
    },
    onAgentComplete: (info) => {
      console.log(`${formatTime()} ✅ Agent complete: ${info.agentId}`);
    },
    onTaskStart: (info) => {
      console.log(`${formatTime()} 📋 Task started: ${info.taskId} - "${info.title}"`);
    },
    onTaskComplete: (info) => {
      console.log(`${formatTime()} ✅ Task complete: ${info.taskId}`);
    },
    onTaskRejected: (info) => {
      console.log(`${formatTime()} ❌ Task rejected: ${info.taskId} - ${info.reason}`);
    },
    onDecision: (info) => {
      console.log(`${formatTime()} 🤝 Decision by ${info.agentId}: ${info.decision}`);
    },
    onError: (info) => {
      console.log(`${formatTime()} ⚠️ Error in ${info.agentId}: ${info.error} (phase: ${info.phase})`);
    },
  };

  if (verbose) {
    callbacks.onTurnStart = (info) => {
      console.log(`${formatTime()} 🔄 Turn ${info.turn} started (agent: ${info.agentId})`);
    };
    callbacks.onTurnEnd = (info) => {
      if (info.contentBlocks && info.contentBlocks.length > 0) {
        for (const block of info.contentBlocks) {
          if (block.type === 'text') {
            console.log(`${formatTime()} 💬 ${block.text}`);
          } else if (block.type === 'thinking') {
            if (block.redacted) {
              console.log(`${formatTime()} 🧠 [redacted thinking]`);
            } else {
              console.log(`${formatTime()} 🧠 ${block.thinking}`);
            }
          }
        }
      }
      if (info.tokens) {
        console.log(`${formatTime()} 📊 Tokens: ${info.tokens.input} in / ${info.tokens.output} out`);
      }
    };
    callbacks.onToolCallStart = (info) => {
      console.log(`${formatTime()} 🔧 ${info.toolName}(${JSON.stringify(info.arguments)}) (agent: ${info.agentId})`);
    };
    callbacks.onToolCallEnd = (info) => {
      const icon = info.isError ? '❌' : '✅';
      const label = info.isError ? 'Tool error' : 'Tool result';
      console.log(`${formatTime()} ${icon} ${label}: ${info.toolName} (agent: ${info.agentId})`);
    };
  }

  return callbacks;
}

// ─── Commands ───────────────────────────────────────────────────────────────

export async function initCommand(_options: CliOptions): Promise<void> {
  await initDefaultConfig();
  const globalDir = getGlobalConfigDir();
  console.log('Initialized engin directory structure at ' + globalDir);
}

export async function runCommand(options: CliOptions): Promise<void> {
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const workflowName = options.workflowName!;

  // Validate workflow name before using it in path construction
  validateWorkflowName(workflowName);

  const workDir = options.workDir ?? getDefaultWorkDir(options.cwd, workflowName);
  const workflow = await loadWorkflow(workflowName, options.cwd);

  // Set up SIGINT handler for cooperative cancellation
  const controller = new AbortController();
  let sigintCount = 0;

  const handler = () => {
    sigintCount++;
    if (sigintCount === 1) {
      console.log(
        `\n${formatTime()} ⏹️  Interrupt received, stopping workflow gracefully... (Ctrl+C again to force quit)`,
      );
      controller.abort();
    } else {
      console.log(`\n${formatTime()} ⏹️  Force quit.`);
      process.exit(1);
    }
  };

  process.on('SIGINT', handler);
  try {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    await workflow.run(options.taskPrompt!, {
      cwd: options.cwd,
      workDir,
      maxConcurrentTasks: options.maxConcurrent,
      apiKeys: Object.keys(options.apiKeys).length > 0 ? options.apiKeys : undefined,
      onStatus: createStatusCallbacks(options.verbose),
      signal: controller.signal,
    });
  } finally {
    process.removeListener('SIGINT', handler);
  }
}

// ─── Main Entry Point ───────────────────────────────────────────────────────

let cliOptions: CliOptions | undefined;

export async function main(): Promise<void> {
  cliOptions = parseArgs(process.argv.slice(2));
  const options = cliOptions;

  // Print any warnings from argument parsing
  for (const warning of options.warnings) {
    process.stderr.write(`Warning: ${warning}\n`);
  }

  // Load .env files for commands that need them (skip for help/version)
  if (options.command !== 'help' && options.command !== 'version') {
    const envResult = loadEnvFiles(options.cwd);
    if (options.verbose && envResult.loadedFiles.length > 0) {
      for (const file of envResult.loadedFiles) {
        console.log(`${formatTime()} 📄 Loaded .env: ${file}`);
      }
    }
  }

  if (options.command === 'help') {
    process.stdout.write(USAGE + '\n');
    process.exit(0);
  }
  if (options.command === 'version') {
    process.stdout.write(`engin v${VERSION}\n`);
    process.exit(0);
  }
  if (options.command === 'init') {
    await initCommand(options);
    return;
  }
  await runCommand(options);
}

const isDirectRun = process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;

if (isDirectRun) {
  main().catch((err) => {
    const msg = err instanceof Error ? (cliOptions?.verbose ? err.stack : err.message) : String(err);
    process.stderr.write(`Error: ${msg}\n`);
    process.exit(1);
  });
}

import { afterEach, beforeEach, describe, expect, it, spyOn } from 'bun:test';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createStatusCallbacks, formatTime, main, parseArgs } from '../src/cli.ts';
import { useEnvSandbox } from './helpers/env-sandbox.js';
import { useTempDir } from './helpers/use-temp-dir.js';

// ─── parseArgs ──────────────────────────────────────────────────────────────

describe('parseArgs', () => {
  it('parses run command with workflowName and taskPrompt', () => {
    const result = parseArgs(['develop', 'build a feature', '--cwd', '/c']);
    expect(result).toEqual({
      command: 'run',
      workflowName: 'develop',
      taskPrompt: 'build a feature',
      cwd: '/c',
      workDir: undefined,
      maxConcurrent: 3,
      verbose: false,
      apiKeys: {},
      warnings: [],
    });
  });

  it('parses run with all options', () => {
    const result = parseArgs([
      'develop',
      'build a feature',
      '--cwd',
      '/c',
      '--work-dir',
      '/w',
      '--max-concurrent',
      '5',
      '--verbose',
      '--api-key',
      'anthropic=sk-xxx',
      '--api-key',
      'openai=pk-yyy',
    ]);
    expect(result.command).toBe('run');
    expect(result.workflowName).toBe('develop');
    expect(result.taskPrompt).toBe('build a feature');
    expect(result.cwd).toBe('/c');
    expect(result.workDir).toBe('/w');
    expect(result.maxConcurrent).toBe(5);
    expect(result.verbose).toBe(true);
    expect(result.apiKeys).toEqual({
      anthropic: 'sk-xxx',
      openai: 'pk-yyy',
    });
  });

  it('parses init command', () => {
    const result = parseArgs(['init']);
    expect(result.command).toBe('init');
  });

  it('throws on missing command', () => {
    expect(() => parseArgs([])).toThrow(/Missing command/);
  });

  it('throws on missing task prompt for run', () => {
    expect(() => parseArgs(['develop'])).toThrow(/Missing required <task-prompt>/);
  });

  it('throws on unknown flag', () => {
    expect(() => parseArgs(['develop', 'task', '--bogus'])).toThrow(/Unknown flag/);
  });

  it('throws on init with extra positional', () => {
    expect(() => parseArgs(['init', 'extra'])).toThrow(/Unexpected argument/);
  });

  it('throws on invalid --api-key format', () => {
    expect(() => parseArgs(['develop', 'task', '--api-key', 'noequals'])).toThrow(/Invalid --api-key format/);
  });

  it('--cwd defaults to process.cwd()', () => {
    const result = parseArgs(['init']);
    expect(result.cwd).toBe(process.cwd());
    expect(result.command).toBe('init');
  });

  it('--max-concurrent defaults to 3', () => {
    const result = parseArgs(['develop', 'task']);
    expect(result.maxConcurrent).toBe(3);
  });

  it('--verbose defaults to false', () => {
    const result = parseArgs(['init']);
    expect(result.verbose).toBe(false);
    expect(result.command).toBe('init');
  });

  it('parses --api-key repeatable', () => {
    const result = parseArgs(['develop', 'task', '--api-key', 'anthropic=sk-xxx', '--api-key', 'openai=pk-yyy']);
    expect(result.apiKeys).toEqual({
      anthropic: 'sk-xxx',
      openai: 'pk-yyy',
    });
  });

  describe('--max-concurrent validation', () => {
    it('accepts valid positive integer', () => {
      const result = parseArgs(['develop', 'task', '--max-concurrent', '5']);
      expect(result.maxConcurrent).toBe(5);
    });

    it('rejects zero', () => {
      expect(() => parseArgs(['develop', 'task', '--max-concurrent', '0'])).toThrow(/positive integer/);
    });

    it('rejects negative number', () => {
      expect(() => parseArgs(['develop', 'task', '--max-concurrent', '-1'])).toThrow(/positive integer/);
    });

    it('rejects float', () => {
      expect(() => parseArgs(['develop', 'task', '--max-concurrent', '1.5'])).toThrow(/positive integer/);
    });

    it('rejects non-numeric string', () => {
      expect(() => parseArgs(['develop', 'task', '--max-concurrent', 'abc'])).toThrow(/positive integer/);
    });

    it('rejects empty string', () => {
      expect(() => parseArgs(['develop', 'task', '--max-concurrent', ''])).toThrow(/positive integer/);
    });
  });

  describe('--help and --version', () => {
    it("--help returns { command: 'help' }", () => {
      const result = parseArgs(['--help']);
      expect(result).toEqual({
        command: 'help',
        cwd: process.cwd(),
        maxConcurrent: 3,
        verbose: false,
        apiKeys: {},
        warnings: [],
      });
    });

    it("-h returns { command: 'help' }", () => {
      const result = parseArgs(['-h']);
      expect(result.command).toBe('help');
    });

    it("--version returns { command: 'version' }", () => {
      const result = parseArgs(['--version']);
      expect(result).toEqual({
        command: 'version',
        cwd: process.cwd(),
        maxConcurrent: 3,
        verbose: false,
        apiKeys: {},
        warnings: [],
      });
    });

    it("-v returns { command: 'version' }", () => {
      const result = parseArgs(['-v']);
      expect(result.command).toBe('version');
    });

    it('--help works when mixed with other args', () => {
      const result = parseArgs(['develop', 'task', '--help']);
      expect(result.command).toBe('help');
    });
  });

  describe('main() handles help and version', () => {
    let exitSpy: ReturnType<typeof spyOn>;
    let stdoutSpy: ReturnType<typeof spyOn>;

    beforeEach(() => {
      exitSpy = spyOn(process, 'exit').mockImplementation(((code: number) => {
        throw new Error(`process.exit(${code})`);
      }) as never);
      stdoutSpy = spyOn(process.stdout, 'write').mockImplementation(() => true);
    });

    afterEach(() => {
      exitSpy.mockRestore();
      stdoutSpy.mockRestore();
    });

    it('main() calls process.exit(0) for --help', async () => {
      const originalArgv = process.argv;
      process.argv = ['node', 'cli.ts', '--help'];
      try {
        await expect(main()).rejects.toThrow('process.exit(0)');
      } finally {
        process.argv = originalArgv;
      }
      expect(exitSpy).toHaveBeenCalledWith(0);
      expect(stdoutSpy).toHaveBeenCalledTimes(1);
      const output = stdoutSpy.mock.calls[0][0] as string;
      expect(output).toContain('Usage:');
    });

    it('main() calls process.exit(0) for --version', async () => {
      const originalArgv = process.argv;
      process.argv = ['node', 'cli.ts', '--version'];
      try {
        await expect(main()).rejects.toThrow('process.exit(0)');
      } finally {
        process.argv = originalArgv;
      }
      expect(exitSpy).toHaveBeenCalledWith(0);
      expect(stdoutSpy).toHaveBeenCalledTimes(1);
      const output = stdoutSpy.mock.calls[0][0] as string;
      expect(output).toContain('engin v');
    });
  });

  it('treats non-keyword first positional as workflow name (implicit run)', () => {
    const result = parseArgs(['my-workflow', 'do something', '--cwd', '/c']);
    expect(result.command).toBe('run');
    expect(result.workflowName).toBe('my-workflow');
    expect(result.taskPrompt).toBe('do something');
  });
});

// ─── formatTime ─────────────────────────────────────────────────────────────

describe('formatTime', () => {
  it('returns bracketed time format', () => {
    const result = formatTime();
    expect(result).toMatch(/^\[\d{2}:\d{2}:\d{2}\]$/);
  });
});

// ─── createStatusCallbacks ─────────────────────────────────────────────────

describe('createStatusCallbacks', () => {
  let logSpy: ReturnType<typeof spyOn>;

  beforeEach(() => {
    logSpy = spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    logSpy.mockRestore();
  });

  it('non-verbose has no agent-level callbacks', () => {
    const callbacks = createStatusCallbacks(false);
    expect(callbacks.onTurnStart).toBeUndefined();
    expect(callbacks.onTurnEnd).toBeUndefined();
    expect(callbacks.onToolCallStart).toBeUndefined();
    expect(callbacks.onToolCallEnd).toBeUndefined();
  });

  it('verbose has agent-level callbacks', () => {
    const callbacks = createStatusCallbacks(true);
    expect(typeof callbacks.onTurnStart).toBe('function');
    expect(typeof callbacks.onTurnEnd).toBe('function');
    expect(typeof callbacks.onToolCallStart).toBe('function');
    expect(typeof callbacks.onToolCallEnd).toBe('function');
  });

  it('onWorkflowStart logs formatted output', () => {
    const callbacks = createStatusCallbacks(false);
    callbacks.onWorkflowStart!({
      taskPrompt: 'build it',
      resumed: false,
      workDir: '/tmp',
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Workflow started/);
  });

  it('onPhaseStart logs formatted output', () => {
    const callbacks = createStatusCallbacks(false);
    callbacks.onPhaseStart!({ phase: 'planning' as never, round: 1 });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Phase started/);
  });

  it('onWorkflowComplete logs duration', () => {
    const callbacks = createStatusCallbacks(false);
    callbacks.onWorkflowComplete!({
      totalDurationMs: 5000,
      agentCount: 3,
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Workflow complete/);
  });

  it('onWorkflowFailed logs error', () => {
    const callbacks = createStatusCallbacks(false);
    callbacks.onWorkflowFailed!({
      error: new Error('boom'),
      phase: 'execution',
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Workflow failed/);
  });

  it('onTurnStart logs in verbose mode', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnStart!({ agentId: 'agent-1', turn: 2 });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Turn/);
  });

  it('onToolCallStart logs tool name and arguments', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onToolCallStart!({
      agentId: 'agent-1',
      toolName: 'read_file',
      toolCallId: 'tc-1',
      arguments: { path: '/foo.ts' },
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    const output = logSpy.mock.calls[0][0] as string;
    expect(output).toContain('read_file');
    expect(output).toContain('/foo.ts');
    expect(output).toContain('agent-1');
  });

  it('onTurnEnd renders text content blocks in verbose mode', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: [{ type: 'text', text: 'Hello world' }],
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/Hello world/);
    expect(logSpy.mock.calls[0][0]).not.toMatch(/Turn .* ended/);
  });

  it('onTurnEnd renders thinking content', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: [{ type: 'thinking', thinking: 'Let me think...' }],
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/🧠/);
    expect(logSpy.mock.calls[0][0]).toMatch(/Let me think\.\.\./);
  });

  it('onTurnEnd renders redacted thinking', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: [{ type: 'thinking', thinking: '', redacted: true }],
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    expect(logSpy.mock.calls[0][0]).toMatch(/redacted thinking/);
  });

  it('onTurnEnd silently ignores toolCall content blocks (regression)', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: [{ type: 'toolCall', id: 'tc1', name: 'read', arguments: { path: '/foo.ts' } }],
    });
    expect(logSpy).not.toHaveBeenCalled();
  });

  it('onTurnEnd renders tokens when present', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: undefined,
      tokens: { input: 100, output: 50 },
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    const output = logSpy.mock.calls[0][0] as string;
    expect(output).toMatch(/Tokens/);
    expect(output).toMatch(/100 in \/ 50 out/);
  });

  it('onTurnEnd produces no output when no content and no tokens', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: undefined,
    });
    expect(logSpy).not.toHaveBeenCalled();
  });

  it('onTurnEnd with multi-line text renders fully', () => {
    const callbacks = createStatusCallbacks(true);
    callbacks.onTurnEnd!({
      agentId: 'a1',
      turn: 1,
      contentBlocks: [{ type: 'text', text: 'line1\nline2\nline3' }],
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    const output = logSpy.mock.calls[0][0] as string;
    expect(output).toContain('line1');
    expect(output).toContain('line2');
    expect(output).toContain('line3');
  });
});

// ─── main() loads .env files ────────────────────────────────────────────────

describe('main() loads .env files', () => {
  useEnvSandbox();
  const { getDir } = useTempDir();

  let exitSpy: ReturnType<typeof spyOn>;
  let logSpy: ReturnType<typeof spyOn>;

  beforeEach(() => {
    exitSpy = spyOn(process, 'exit').mockImplementation(((code: number) => {
      throw new Error(`process.exit(${code})`);
    }) as never);
    logSpy = spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    exitSpy.mockRestore();
    logSpy.mockRestore();
  });

  it('loads .env from .engin/.env for init command', async () => {
    // Create .engin/.env in temp dir
    const harnessDir = join(getDir(), '.engin');
    mkdirSync(harnessDir, { recursive: true });
    writeFileSync(join(harnessDir, '.env'), 'TEST_CLI_ENV_VAR=from_cli_test\n');

    // Point global config to temp so initDefaultConfig() writes there
    const originalXdg = process.env.XDG_CONFIG_HOME;
    process.env.XDG_CONFIG_HOME = join(getDir(), 'global');

    const originalArgv = process.argv;
    process.argv = ['node', 'cli.ts', 'init', '--cwd', getDir()];
    try {
      await main();
    } finally {
      process.argv = originalArgv;
      if (originalXdg === undefined) {
        delete process.env.XDG_CONFIG_HOME;
      } else {
        process.env.XDG_CONFIG_HOME = originalXdg;
      }
    }

    expect(process.env.TEST_CLI_ENV_VAR).toBe('from_cli_test');
  });

  it('does not load .env files for help command', async () => {
    const harnessDir = join(getDir(), '.engin');
    mkdirSync(harnessDir, { recursive: true });
    writeFileSync(join(harnessDir, '.env'), 'TEST_CLI_ENV_VAR_HELP=should_not_appear\n');

    const originalArgv = process.argv;
    process.argv = ['node', 'cli.ts', '--help', '--cwd', getDir()];
    try {
      await expect(main()).rejects.toThrow('process.exit(0)');
    } finally {
      process.argv = originalArgv;
    }

    expect(process.env.TEST_CLI_ENV_VAR_HELP).toBeUndefined();
  });

  it('does not load .env files for version command', async () => {
    const harnessDir = join(getDir(), '.engin');
    mkdirSync(harnessDir, { recursive: true });
    writeFileSync(join(harnessDir, '.env'), 'TEST_CLI_ENV_VAR_VERSION=should_not_appear\n');

    const originalArgv = process.argv;
    process.argv = ['node', 'cli.ts', '--version', '--cwd', getDir()];
    try {
      await expect(main()).rejects.toThrow('process.exit(0)');
    } finally {
      process.argv = originalArgv;
    }

    expect(process.env.TEST_CLI_ENV_VAR_VERSION).toBeUndefined();
  });
});

/**
 * WebSocket protocol types for the engin web interface.
 *
 * These types define the message protocol between the server and connected
 * clients (e.g. the web UI). All messages are JSON-serialisable.
 *
 * Discriminated unions use the `type` field as the discriminant.
 */

// ─── Shared value types ─────────────────────────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages ───────────────────────────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages ───────────────────────────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Server options ─────────────────────────────────────────────────────────

export interface WebServerOptions {
  host: string;
  port: number;
  cwd: string;
}

import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
import type { ServerMessage, ClientMessage, WebServerOptions } from './types.js';
import { RunRegistry } from './run-registry.js';
import { createStatusBridge } from './status-bridge.js';
import { loadWorkflow } from '../core/workflow-loader.js';
import { getDefaultWorkDir } from '../core/config.js';

export async function startWebServer(options: WebServerOptions): Promise<Bun.Server> {
  const registry = new RunRegistry();
  const clients = new Set<any>();
  const WEB_DIST_DIR = join(import.meta.dir, '..', '..', 'web', 'dist');

  const broadcast = (msg: ServerMessage) => {
    const d = JSON.stringify(msg);
    for (const ws of clients) {
      ws.send(d);
    }
  };

  const MIME_MAP: Record<string, string> = {
    '.html': 'text/html',
    '.js': 'application/javascript',
    '.css': 'text/css',
    '.json': 'application/json',
    '.png': 'image/png',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
    '.woff': 'font/woff',
    '.woff2': 'font/woff2',
  };

  async function startWorkflow(workflowName: string, taskPrompt: string, maxConcurrent?: number): Promise<string> {
    const runId = registry.createRun(workflowName);
    broadcast({ type: 'workflow_started', summary: registry.getSummary(runId) });

    let workflow;
    try {
      workflow = await loadWorkflow(workflowName, options.cwd);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      const summary = registry.failRun(runId, msg);
      broadcast({ type: 'workflow_failed', summary, error: msg, phase: registry.getRun(runId)?.currentPhase ?? 'unknown' });
      return runId;
    }

    const bridge = createStatusBridge(runId, registry, broadcast);
    const workDir = getDefaultWorkDir(options.cwd, workflowName);

    // Fire-and-forget the workflow run
    workflow
      .run(taskPrompt, {
        cwd: options.cwd,
        workDir,
        maxConcurrentTasks: maxConcurrent,
        onStatus: bridge,
        signal: registry.getAbortController(runId)!.signal,
      })
      .then(() => {
        const summary = registry.completeRun(runId);
        broadcast({ type: 'workflow_complete', summary });
      })
      .catch((err: unknown) => {
        const msg = err instanceof Error ? err.message : String(err);
        const summary = registry.failRun(runId, msg);
        broadcast({ type: 'workflow_failed', summary, error: msg, phase: registry.getRun(runId)?.currentPhase ?? 'unknown' });
      });

    return runId;
  }

  const server = Bun.serve({
    hostname: options.host,
    port: options.port,

    async fetch(req, server) {
      // ─── WebSocket upgrade ────────────────────────────────────────────
      if (new URL(req.url).pathname === '/ws') {
        const upgraded = server.upgrade(req);
        if (!upgraded) {
          return new Response('WebSocket upgrade failed', { status: 400 });
        }
        return undefined;
      }
      const url = new URL(req.url);

      // ─── API routes ────────────────────────────────────────────────────
      if (url.pathname.startsWith('/api/')) {
        if (req.method === 'POST' && url.pathname === '/api/runs') {
          return (async () => {
            try {
              const body = (await req.json()) as { workflowName?: string; taskPrompt?: string; maxConcurrent?: number };
              if (!body.workflowName || !body.taskPrompt) {
                return new Response(JSON.stringify({ error: 'workflowName and taskPrompt are required' }), {
                  status: 400,
                  headers: { 'Content-Type': 'application/json' },
                });
              }
              const runId = await startWorkflow(body.workflowName, body.taskPrompt, body.maxConcurrent);
              return Response.json({ runId });
            } catch {
              return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
                status: 400,
                headers: { 'Content-Type': 'application/json' },
              });
            }
          })();
        }

        if (req.method === 'GET' && url.pathname === '/api/runs') {
          return Response.json(registry.getAllSummaries());
        }

        return new Response('Not Found', { status: 404 });
      }

      // ─── Static file serving ───────────────────────────────────────────
      let filePath = url.pathname === '/' ? '/index.html' : url.pathname;

      // Try to serve the requested file
      const fullPath = join(WEB_DIST_DIR, filePath);
      const ext = extname(filePath);

      try {
        const content = await readFile(fullPath);
        const mimeType = MIME_MAP[ext] ?? 'application/octet-stream';

        // Special handling for index.html – replace WS endpoint
        if (filePath === '/index.html') {
          const text = content.toString('utf-8');
          const wsEndpoint = `ws://${url.host}/ws`;
          const modified = text.replace('{{WS_ENDPOINT}}', wsEndpoint);
          return new Response(modified, {
            headers: { 'Content-Type': 'text/html' },
          });
        }

        return new Response(content, {
          headers: { 'Content-Type': mimeType },
        });
      } catch {
        // File not found – try index.html (SPA fallback) or placeholder
        try {
          const indexPath = join(WEB_DIST_DIR, 'index.html');
          const indexContent = await readFile(indexPath);
          const text = indexContent.toString('utf-8');
          const wsEndpoint = `ws://${url.host}/ws`;
          const modified = text.replace('{{WS_ENDPOINT}}', wsEndpoint);
          return new Response(modified, {
            headers: { 'Content-Type': 'text/html' },
          });
        } catch {
          // No index.html at all – placeholder
          return new Response(
            `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>engin</title></head>
<body>
  <h1>engin</h1>
  <p>Frontend not built. Run <code>cd web && npm run build</code>.</p>
  <script>window.__WS_ENDPOINT__ = "ws://${url.host}/ws";</script>
</body>
</html>`,
            {
              status: 200,
              headers: { 'Content-Type': 'text/html' },
            },
          );
        }
      }
    },

    websocket: {
      open(ws) {
        clients.add(ws);
        ws.send(JSON.stringify({ type: 'init', workflows: registry.getAllSummaries() }));
      },
      message(ws, msg) {
        let parsed: ClientMessage;
        try {
          parsed = JSON.parse(typeof msg === 'string' ? msg : msg.toString()) as ClientMessage;
        } catch {
          return; // Ignore invalid messages
        }

        switch (parsed.type) {
          case 'start_workflow': {
            // Fire and forget – don't await
            startWorkflow(parsed.workflowName, parsed.taskPrompt, parsed.maxConcurrent).catch(() => {});
            break;
          }
          case 'cancel_workflow': {
            const ctrl = registry.getAbortController(parsed.workflowId);
            if (ctrl) {
              ctrl.abort();
            }
            break;
          }
          case 'select_workflow': {
            // Currently no server-side action needed for selection
            break;
          }
        }
      },
      close(ws) {
        clients.delete(ws);
      },
    },
  });

  console.log(`Web server listening on http://${options.host}:${options.port}`);
  return server;
}

